import unittest
from solution import parse_csv_line

class TestParseCSV(unittest.TestCase):
    def test_simple(self):
        self.assertEqual(parse_csv_line("a, b, c"), ["a", "b", "c"])

    def test_quoted_commas(self):
        self.assertEqual(parse_csv_line('"John, Jr.", 25, Engineer'), ["John, Jr.", "25", "Engineer"])

    def test_escaped_quotes(self):
        self.assertEqual(parse_csv_line('"He said ""Hello""", ok'), ['He said "Hello"', "ok"])

    def test_empty_fields(self):
        self.assertEqual(parse_csv_line('a,,c'), ["a", "", "c"])

if __name__ == '__main__':
    unittest.main()
